package bsdiff

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

// Fixtures were generated by the untouched original executable, not Build.
// Compare compressed bytes as well as decoding original patches independently
// of the reconstruction's encoder. This catches toolchain compression changes.
func TestOriginalExecutablePatches(t *testing.T) {
	var fixtures struct {
		Blobs map[string][]byte
		Cases []struct{ Name, Old, New, Patch string }
	}
	raw, err := os.ReadFile("testdata/original.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw, &fixtures); err != nil {
		t.Fatal(err)
	}
	if len(fixtures.Cases) < 10 {
		t.Fatal("missing original fixtures")
	}
	for _, c := range fixtures.Cases {
		t.Run(c.Name, func(t *testing.T) {
			old, next, want := fixtures.Blobs[c.Old], fixtures.Blobs[c.New], fixtures.Blobs[c.Patch]
			if len(old) == 0 || len(next) == 0 || len(want) == 0 {
				t.Fatal("missing fixture blob")
			}
			got, err := Build(old, next)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, want) {
				t.Fatalf("patch differs from original: got %d bytes, want %d", len(got), len(want))
			}
			applied, err := Apply(old, want)
			if err != nil || !bytes.Equal(applied, next) {
				t.Fatal("cannot decode original patch", err)
			}
		})
	}
}

func TestOriginalEmptyInputBehavior(t *testing.T) {
	for _, pair := range [][2][]byte{{nil, nil}, {nil, []byte("new")}, {[]byte("old"), nil}} {
		if _, err := Build(pair[0], pair[1]); err == nil || err.Error() != "bsdiff: empty input" {
			t.Fatal("original rejects empty inputs", err)
		}
	}
}
